/**
 * Clean-slate session handoff payload (ROADMAP 11.5).
 *
 * Pure assembly of the structured payload a fresh session is seeded with when the
 * owner hands off a context-limited session:
 *
 * 1. Active decisions and architecture constraints — from the vault `Synthesis.md`
 *    note (`<vault>/Cindy/Memory/Synthesis.md`, generated by 6.3) plus anything the
 *    caller passes in.
 * 2. The uncommitted working tree state — modified file list and `git diff` body.
 * 3. Pending next steps and unresolved questions — the note's `Next Actions` and
 *    `Open Questions` sections merged with caller-supplied items (e.g. extracted
 *    from the outgoing session's transcript).
 *
 * Discipline:
 * - Every text that reaches the payload passes `redactSecrets` first.
 * - The diff body is fenced adaptively, so author content cannot break out of the
 *   payload's structure (same rule as the skill manifest's fixed boundary).
 * - The result reports its estimated token count and enforces a total budget.
 *   Allocation keeps what cannot be re-derived longest: constraints first, then
 *   questions, then next steps; the diff is trimmed first because git can
 *   regenerate it. Truncation is always explicit — a marker states what was cut.
 * - No I/O and no imports beyond the redactor: the caller (host IPC) gathers
 *   sources; this module only assembles.
 */

import { redactSecrets } from '../export/session-markdown';

export interface SessionHandoffSources {
  /** Raw text of the vault `Synthesis.md` note; its sections are extracted. */
  synthesis?: string | null;
  /** `git diff` output for uncommitted tracked changes in the session workdir. */
  gitDiff?: string | null;
  /** Modified / untracked file paths (e.g. from `git status --porcelain`). */
  modifiedFiles?: readonly string[];
  /** Task-level settled decisions, merged with the note's `Key Decisions` section. */
  activeDecisions?: readonly string[];
  /** Constraints the owner stated in chat (ROADMAP 11.5 follow-up); rendered first in section 1. */
  constraints?: readonly string[];
  /** Task-level next steps, merged with the note's `Next Actions` section. */
  pendingNextSteps?: readonly string[];
  /** Task-level open questions, merged with the note's `Open Questions` section. */
  unresolvedQuestions?: readonly string[];
  /** Session working directory shown to the fresh session. */
  workingDir?: string | null;
  /** Title of the session being handed off (breadcrumb only). */
  sessionTitle?: string | null;
  /** ISO timestamp; defaults to now. Tests pass a fixed value. */
  generatedAt?: string;
}

export interface SessionHandoffOptions {
  /** Total payload budget in estimated tokens. Default 4000. */
  maxPromptTokens?: number;
  /** Pre-cap on the diff body, in characters. Default 12000. */
  maxDiffChars?: number;
  /** Pre-cap on each synthesis-derived body, in characters. Default 6000. */
  maxSynthesisChars?: number;
  /** Max list items kept per steps/questions list. Default 40. */
  maxListItems?: number;
  /** Max characters kept per list item. Default 240. */
  maxItemChars?: number;
}

export interface SessionHandoffTruncation {
  /** The diff body was cut to fit `maxDiffChars` or the token budget. */
  diff: boolean;
  /** A synthesis-derived body was cut to fit `maxSynthesisChars` or the budget. */
  synthesis: boolean;
  /** The assembled prompt still exceeded the budget and was hard-clipped. */
  payload: boolean;
}

export interface SessionHandoffPayload {
  /** The ready-to-seed prompt. Already redacted; never contains a raw secret. */
  prompt: string;
  /** Estimated tokens of `prompt` (UTF-8 bytes / 4, rounded up). */
  tokenCount: number;
  truncated: SessionHandoffTruncation;
}

export interface SynthesisSections {
  /** `Key Decisions & Architecture`-style section(s). */
  constraints: string;
  /** `Open Questions & Blockers`-style section(s). */
  questions: string;
  /** `Next Actions & Pending Tasks`-style section(s). */
  nextSteps: string;
}

export const DEFAULT_MAX_PROMPT_TOKENS = 4000;
export const DEFAULT_MAX_DIFF_CHARS = 12_000;
export const DEFAULT_MAX_SYNTHESIS_CHARS = 6_000;
export const DEFAULT_MAX_LIST_ITEMS = 40;
export const DEFAULT_MAX_ITEM_CHARS = 240;

const NONE_PLACEHOLDER = 'None recorded.';

/**
 * Estimated token count: UTF-8 bytes over 4, rounded up. Deliberately cheap and
 * dependency-free (the same approximation the skill engine uses); it is a budget
 * guard, not billing.
 */
export function estimateHandoffTokens(text: string): number {
  return Math.ceil(new TextEncoder().encode(text).length / 4);
}

function classifyHeading(heading: string): keyof SynthesisSections | null {
  const lower = heading.toLowerCase();
  if (/(question|blocker)/.test(lower)) return 'questions';
  if (/(next step|next action|pending|follow.?up|todo|action)/.test(lower)) return 'nextSteps';
  if (/(decision|constraint|architecture|rationale)/.test(lower)) return 'constraints';
  return null;
}

/**
 * Split a `Synthesis.md` body into the three payload buckets. Headings are
 * classified by keyword (the 6.3 writer emits `Key Decisions & Architecture`,
 * `Open Questions & Blockers`, `Next Actions & Pending Tasks`; hand-edits with
 * equivalent wording map the same way). Text before the first `## ` heading is
 * ignored when any recognised section exists; when nothing is recognised the
 * whole note is kept as constraints, so a hand-written note is never dropped.
 */
export function extractSynthesisSections(text: string): SynthesisSections {
  const empty: SynthesisSections = { constraints: '', questions: '', nextSteps: '' };
  if (!text.trim()) return empty;

  const buckets: Record<keyof SynthesisSections, string[]> = {
    constraints: [],
    questions: [],
    nextSteps: [],
  };
  const headingRe = /^##\s+(.+)$/gm;
  const matches = [...text.matchAll(headingRe)];
  for (const [index, match] of matches.entries()) {
    const kind = classifyHeading(match[1] ?? '');
    if (!kind) continue;
    const start = (match.index ?? 0) + match[0].length;
    const end = matches[index + 1]?.index ?? text.length;
    const body = text.slice(start, end).trim();
    if (body) buckets[kind].push(body);
  }

  const constraints = buckets.constraints.join('\n\n');
  const questions = buckets.questions.join('\n\n');
  const nextSteps = buckets.nextSteps.join('\n\n');
  if (!constraints && !questions && !nextSteps) {
    return { constraints: text.trim(), questions: '', nextSteps: '' };
  }
  return { constraints, questions, nextSteps };
}

export interface SessionHandoffMessage {
  role: string;
  content?: string;
  text?: string;
}

/**
 * Open questions from the outgoing session: interrogative sentences in the final
 * message. Nothing after it can have answered them, so they are unresolved by
 * construction; older questions were either answered later or dropped on
 * purpose. A heuristic — the handoff never claims more than it knows.
 */
export function extractOpenQuestions(
  messages: readonly SessionHandoffMessage[],
): string[] {
  const last = messages[messages.length - 1];
  if (!last || (last.role !== 'user' && last.role !== 'assistant')) return [];
  const text = (last.content || last.text || '').trim();
  const matches = text.match(/[^.!?\n]+\?/g) ?? [];
  return dedupe(matches.map((question) => question.trim()));
}

/** A backtick fence longer than any run of backticks inside `body`. */
function fenceFor(body: string): string {
  const longest = Math.max(0, ...(body.match(/`+/g) ?? []).map((run) => run.length));
  return '`'.repeat(Math.max(3, longest + 1));
}

function sliceUtf8(text: string, maxBytes: number): string {
  const encoder = new TextEncoder();
  let out = '';
  let bytes = 0;
  for (const char of text) {
    const size = encoder.encode(char).length;
    if (bytes + size > maxBytes) break;
    out += char;
    bytes += size;
  }
  return out;
}

function truncationMarker(label: string, kept: number, total: number): string {
  return `\n... [${label} truncated: ${total - kept} of ${total} characters omitted]`;
}

function renderBullets(
  items: readonly string[],
  maxItems: number,
  maxItemChars: number,
): string {
  const kept = items.slice(0, maxItems).map((item) =>
    item.length > maxItemChars ? `${item.slice(0, maxItemChars)}…` : item,
  );
  const lines = kept.map((item) => `- ${item}`);
  if (items.length > maxItems) {
    lines.push(`- [${items.length - maxItems} more items omitted]`);
  }
  return lines.join('\n');
}

function renderMergedSection(bullets: string, body: string): string {
  const parts = [bullets, body].filter(Boolean);
  return parts.join('\n\n') || NONE_PLACEHOLDER;
}

function dedupe(items: readonly string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of items) {
    const item = raw.trim();
    if (!item || seen.has(item)) continue;
    seen.add(item);
    out.push(item);
  }
  return out;
}

/**
 * Machine-readable stamp on every clean-slate payload (ROADMAP 11.5 follow-up).
 *
 * A handoff of a handoff re-read its own payload as if it were conversation, so
 * section 3 re-listed steps the fresh session had already done. The marker lets the
 * next handoff recognise a payload, read its step list back, and drop the items the
 * later turns report as done. Invisible in the rendered prompt (an HTML comment),
 * and recognised by its opening heading for payloads written before it existed.
 */
export const CLEAN_SLATE_HANDOFF_MARKER = '<!-- cindy-clean-slate-handoff:v1 -->';

const LEGACY_PAYLOAD_HEADINGS = [
  '# Session handoff — clean slate',
  '# Session Continuation & Handoff',
];

/** True when this text is a handoff payload rather than a real conversation turn. */
export function isCleanSlateHandoffText(text: string | null | undefined): boolean {
  const trimmed = (text ?? '').trimStart();
  if (!trimmed) return false;
  if (trimmed.startsWith(CLEAN_SLATE_HANDOFF_MARKER)) return true;
  return LEGACY_PAYLOAD_HEADINGS.some((heading) => trimmed.startsWith(heading));
}

/**
 * The pending steps a payload carried, read back out of section 3. Both generated
 * shapes are accepted (`## 3. Pending next steps` / `## Pending Next Actions`) and
 * the overflow marker `- [N more items omitted]` is ignored, so a chained handoff
 * carries exactly what was still outstanding.
 */
export function parseCleanSlateHandoffPendingSteps(payload: string): string[] {
  const lines = (payload ?? '').split(/\r?\n/);
  const headingIndex = lines.findIndex((line) =>
    /^##\s*(?:\d+\.\s*)?(?:pending next steps|pending next actions)\s*$/i.test(line.trim()),
  );
  if (headingIndex === -1) return [];
  const items: string[] = [];
  for (let i = headingIndex + 1; i < lines.length; i++) {
    const line = lines[i]!.trim();
    if (/^##\s/.test(line)) break;
    const match = /^-\s+(?:\[ \]\s*)?(.*)$/.exec(line);
    if (!match) continue;
    const item = match[1]!.trim();
    if (!item || /^\[\d+ more items omitted\]$/.test(item)) continue;
    if (!items.includes(item)) items.push(item);
  }
  return items.slice(0, DEFAULT_MAX_LIST_ITEMS);
}

const COMPLETION_CUE =
  /\b(?:done|completed|finished|added|appended|created|wrote|written|updated|implemented|merged|committed|passed|fixed|removed)\b/i;

const STEP_STOPWORDS = new Set([
  'the', 'and', 'for', 'with', 'that', 'this', 'then', 'into', 'from', 'your', 'you',
  'run', 'all', 'any', 'not', 'but', 'its', 'our', 'now', 'next', 'step', 'steps',
]);

/** Crude, deterministic stemming: enough to match "append" ↔ "appended". */
function stemToken(token: string): string {
  return token.replace(/(?:ed|ing|es|s)$/, '');
}

function salientTokens(text: string): string[] {
  return (text.toLowerCase().match(/[a-z0-9_]+/g) ?? [])
    .map(stemToken)
    .filter((token) => token.length >= 3 && !STEP_STOPWORDS.has(token));
}

/**
 * Drop carried steps that the turns after the payload already report as done.
 *
 * One rule, deliberately strict: a *single* later assistant sentence must contain
 * both a completion cue and **every** salient word of the step. Anything less keeps
 * the step pending — repeating a step the owner sees is recoverable, silently
 * dropping an outstanding one is not. "Done. Run the gates next." therefore keeps
 * "Run the gates" (the cue and the words are in different sentences).
 */
export function filterCompletedPendingSteps(
  items: readonly string[],
  laterMessages: readonly SessionHandoffMessage[],
): string[] {
  const sentences = laterMessages
    .filter((m) => m.role === 'assistant')
    .flatMap((m) => ((m.content || m.text || '').split(/(?:\r?\n)+|(?<=[.!?])\s+/)))
    .map((s) => s.trim())
    .filter(Boolean);
  return items.filter((item) => {
    const needed = [...new Set(salientTokens(item))];
    if (needed.length === 0) return true;
    return !sentences.some((sentence) => {
      if (!COMPLETION_CUE.test(sentence)) return false;
      const present = new Set(salientTokens(sentence));
      return needed.every((token) => present.has(token));
    });
  });
}

/**
 * Assemble the clean-slate handoff prompt. Pure: same inputs, same output.
 */
export function assembleSessionHandoff(
  sources: SessionHandoffSources,
  options: SessionHandoffOptions = {},
): SessionHandoffPayload {
  const maxPromptTokens = options.maxPromptTokens ?? DEFAULT_MAX_PROMPT_TOKENS;
  const maxDiffChars = options.maxDiffChars ?? DEFAULT_MAX_DIFF_CHARS;
  const maxSynthesisChars = options.maxSynthesisChars ?? DEFAULT_MAX_SYNTHESIS_CHARS;
  const maxListItems = options.maxListItems ?? DEFAULT_MAX_LIST_ITEMS;
  const maxItemChars = options.maxItemChars ?? DEFAULT_MAX_ITEM_CHARS;

  const sections = extractSynthesisSections(sources.synthesis ?? '');
  const files = dedupe(sources.modifiedFiles ?? []);
  const decisionItems = dedupe(sources.activeDecisions ?? []);
  const constraintItems = dedupe(sources.constraints ?? []);
  const stepItems = dedupe(sources.pendingNextSteps ?? []);
  const questionItems = dedupe(sources.unresolvedQuestions ?? []);

  // Redact before anything else: no section may leak a credential into a prompt
  // that is stored as a draft and sent to a provider.
  const constraints = redactSecrets(sections.constraints);
  const questionsBody = redactSecrets(sections.questions);
  const stepsBody = redactSecrets(sections.nextSteps);
  const diffText = redactSecrets((sources.gitDiff ?? '').trim());
  const fileBullets = renderBullets(
    files.map((f) => redactSecrets(f)),
    maxListItems,
    maxItemChars,
  );
  const decisionBullets = renderBullets(
    decisionItems.map((d) => redactSecrets(d)),
    maxListItems,
    maxItemChars,
  );
  // Owner-stated constraints ride the same fitted body as the note's constraints, so
  // the budget can never drop them for the diff.
  const constraintBullets = renderBullets(
    constraintItems.map((c) => redactSecrets(c)),
    maxListItems,
    maxItemChars,
  );
  const constraintsBody = [
    constraintBullets ? `Owner-stated constraints (do not violate):\n${constraintBullets}` : '',
    constraints,
  ]
    .filter(Boolean)
    .join('\n\n');
  const stepBullets = renderBullets(
    stepItems.map((s) => redactSecrets(s)),
    maxListItems,
    maxItemChars,
  );
  const questionBullets = renderBullets(
    questionItems.map((q) => redactSecrets(q)),
    maxListItems,
    maxItemChars,
  );
  const dirLine = redactSecrets((sources.workingDir ?? '').trim() || 'unknown');
  const titleLine = redactSecrets((sources.sessionTitle ?? '').trim());
  const generatedAt = sources.generatedAt ?? new Date().toISOString();

  // Budget: measure the fixed frame (everything except the four fitted bodies)
  // exactly by rendering it once with empty bodies, then allocate the remainder
  // in priority order — what cannot be re-derived is kept longest.
  const render = (bodies: {
    constraints: string;
    questionsBody: string;
    stepsBody: string;
    diff: string;
  }): string => {
    const fence = fenceFor(bodies.diff);
    const diffBlock = bodies.diff
      ? ['Uncommitted diff (unified, secrets redacted):', `${fence}diff`, bodies.diff, fence].join(
          '\n',
        )
      : 'No uncommitted changes.';
    return [
      CLEAN_SLATE_HANDOFF_MARKER,
      '# Session handoff — clean slate',
      '',
      'You are a fresh session taking over this work. Everything you need to continue is',
      'below. Continue the task directly from the state described here: do not ask the',
      'owner questions that this handoff already answers.',
      '',
      `- Working directory: ${dirLine}`,
      `- Handoff generated: ${generatedAt}`,
      ...(titleLine ? [`- Handoff from session: ${titleLine}`] : []),
      '',
      '## 1. Active decisions and architecture constraints',
      '',
      // Constraints first: they are the thing a fresh session must not violate.
      renderMergedSection(bodies.constraints, decisionBullets),
      '',
      '## 2. Working tree state (uncommitted)',
      '',
      `Files with uncommitted changes (${files.length}):`,
      '',
      fileBullets || NONE_PLACEHOLDER,
      '',
      diffBlock,
      '',
      '## 3. Pending next steps',
      '',
      renderMergedSection(stepBullets, bodies.stepsBody),
      '',
      '## 4. Unresolved questions',
      '',
      renderMergedSection(questionBullets, bodies.questionsBody),
      '',
    ].join('\n');
  };

  const emptyBodies = { constraints: '', questionsBody: '', stepsBody: '', diff: '' };
  const frameBytes = new TextEncoder().encode(render(emptyBodies)).length;
  // The reserve covers the diff block's header and fence plus truncation markers.
  let remaining = Math.max(0, maxPromptTokens * 4 - frameBytes - 128);

  // Allocation priority: what cannot be re-derived is kept longest — constraints
  // (settled decisions), then open questions, then next steps; the diff is trimmed
  // first because git can regenerate it from the file list above it.
  const wants: Array<[keyof typeof emptyBodies, string, string, number]> = [
    ['constraints', constraintsBody, 'handoff section', maxSynthesisChars],
    ['questionsBody', questionsBody, 'handoff section', maxSynthesisChars],
    ['stepsBody', stepsBody, 'handoff section', maxSynthesisChars],
    ['diff', diffText, 'diff', maxDiffChars],
  ];
  const kept: Record<keyof typeof emptyBodies, string> = {
    constraints: '',
    questionsBody: '',
    stepsBody: '',
    diff: '',
  };
  const cut: Record<keyof typeof emptyBodies, boolean> = {
    constraints: false,
    questionsBody: false,
    stepsBody: false,
    diff: false,
  };
  for (const [key, text, label, preCap] of wants) {
    const capped = text.length > preCap ? text.slice(0, preCap) : text;
    const body = sliceUtf8(capped, remaining);
    if (body.length < text.length) {
      kept[key] = body + truncationMarker(label, body.length, text.length);
      cut[key] = true;
    } else {
      kept[key] = body;
    }
    remaining = Math.max(0, remaining - new TextEncoder().encode(kept[key]).length);
  }

  const prompt = render(kept);
  // Backstop: sliceUtf8 makes the clip byte-exact, so the estimate cannot exceed
  // the budget even for multi-byte text.
  const finalPrompt =
    estimateHandoffTokens(prompt) > maxPromptTokens
      ? `${sliceUtf8(prompt, maxPromptTokens * 4 - 64)}\n... [handoff payload clipped to fit the token budget]`
      : prompt;

  return {
    prompt: finalPrompt,
    tokenCount: estimateHandoffTokens(finalPrompt),
    truncated: {
      diff: cut.diff,
      synthesis: cut.constraints || cut.questionsBody || cut.stepsBody,
      payload: finalPrompt !== prompt,
    },
  };
}
